    if(flow.kind==='auto'){if(!d.datasets.length)return 'Select at least one eligible dataset.';if(!(Number(d.all)>0&&Number(d.all)<Number(d.daily)&&Number(d.daily)<Number(d.weekly)))return 'History windows must increase: every snapshot, daily, then weekly.';if(!d.prefix.trim())return 'Enter a snapshot prefix.';}
    if(flow.kind==='job'){if(!d.destination.trim().includes('/')||d.destination===d.source||/\s|@/.test(d.destination))return 'Choose a destination dataset below an existing parent, different from the source.';if(d.transport==='ssh'&&!state.shared.host)return 'Set up the shared SSH connection before continuing.';if(flow.step===2&&reviewNeeded()&&(!d.reviewed||Date.now()>flow.reviewExpires))return 'Review the existing source checkpoints before saving this cleanup policy.';}
